import {renderColourProposals} from './prop-colour-themes.js';
import {propMouthCarryable} from './props-model.js';
import {clone,lineCells} from './model.js';
import {frameAt} from './playback.js';
import {createAutosaver} from './autosave.js';
import {PROP_WIDTH,PROP_HEIGHT,newPropWorkspace,validatePropWorkspace,propBounds,addPropPlacement,captureProp,paintProp,confirmProp,refreshPropCatalogue,propFamilyLabel,reconcilePropWorkspaces} from './props-model.js';
const PROP_CACHE='cat-studio.props-workspace.v1';
export function installPropsLab({dialog,library,getSequences,actor,download,toast}){
 dialog.classList.add('props-lab');dialog.innerHTML=`<div class="dialog-head"><div><h2>Props lab</h2><small>Draw freely → box loose artwork → label → Done. Saved props can be placed again.</small></div><p id="props-save-status" role="status"></p><button id="props-save-now" hidden>Retry save</button></div><details class="props-recovery" hidden><summary>Workspace recovery &amp; backups</summary><p id="props-recovery-message"></p><button id="props-recover-merge">Reconcile copies</button><button id="props-reload">Use saved copy</button><button id="props-recovery-download">Download original copies</button></details><div class="props-layout"><aside class="props-catalogue"><h3>Catalogue</h3><input id="prop-search" type="search" aria-label="Find a prop" placeholder="Find a prop…"><label>Show<select id="prop-catalogue-filter" aria-label="Catalogue filter"><option value="all">All props</option><option value="ai">AI drafts for review</option><option value="authored">Originals &amp; saved refinements</option></select></label><p class="hint">Click a prop to add an editable placement. Originals are retained when you save a variant.</p><p id="prop-catalogue-count" class="hint" role="status"></p><div id="prop-catalogue"></div><button id="props-export">Export workspace JSON</button></aside><section class="props-workbench"><div class="prop-toolbar" role="toolbar" aria-label="Prop tools"><button data-prop-tool="draw">Draw</button><button data-prop-tool="erase">Erase</button><button data-prop-tool="fill">Fill</button><button data-prop-tool="pick">Pick colour</button><button data-prop-tool="box">Box new prop</button><button data-prop-tool="move">Move / select</button><button id="prop-new">New drawing</button><button id="prop-undo">Undo</button><button id="prop-redo">Redo</button></div><div class="prop-paint-options"><label>Colour<input id="prop-colour" type="color" value="#4da6ff"></label><div id="prop-swatches"></div><label><input id="prop-grid" type="checkbox" checked>Grid</label><label>Zoom<select id="prop-zoom"><option value="4" selected>4×</option><option value="6">6×</option><option value="8">8×</option><option value="12">12×</option></select></label><label>Artist<select id="prop-artist"><option value="human">Human</option><option value="ai">AI</option></select></label></div><p id="prop-canvas-hint" class="hint">Left-click draws; right-click erases. Use Box new prop around loose artwork, then Done.</p><div class="prop-canvas-scroll"><canvas id="prop-canvas" tabindex="0" aria-label="Props drawing canvas, 96 by 64 pixels"></canvas></div><div class="props-placement-list"><h3>Canvas placements</h3><div id="prop-placements"></div></div></section><aside class="props-details"><h3>Selected artwork</h3><p id="prop-selection-info">No selection · painting loose artwork</p><details><summary>Precise capture box</summary><label>Box X<input id="prop-box-x" type="number" min="0" max="95" value="46"></label><label>Box Y<input id="prop-box-y" type="number" min="0" max="63" value="30"></label><label>Box width<input id="prop-box-width" type="number" min="1" max="96" value="5"></label><label>Box height<input id="prop-box-height" type="number" min="1" max="64" value="5"></label><button id="prop-set-box">Select capture box</button></details><div id="prop-edit-controls"><label>Prop label<input id="prop-name" maxlength="120" placeholder="e.g. Blue ball"></label><label>Tags<input id="prop-tags" placeholder="toy, ball, blue"></label><label>Visual notes<textarea id="prop-description" maxlength="2000" placeholder="Size, use, variation ideas…"></textarea></label><label>Behaviour / animation notes<textarea id="prop-behaviour" rows="7" maxlength="6000" placeholder="For example: this mouse rolls back and forth along a shelf, pauses when noticed, and gets nudged away when pounced on. The frayed state is the same toy after lots of play."></textarea></label><p class="hint">Describe movement, interactions, animation timing and how family states relate. Save with Done. Codex reviews these notes with the artwork before implementing behaviour.</p><label><input id="prop-mouth-carryable" type="checkbox"> Can be picked up in the mouth</label><details><summary>Prop family and state</summary><p class="hint">Related states share a stable family ID. Angle, fill and condition describe alternatives; they are not automatically animation frames.</p><label>Family ID<input id="prop-family" maxlength="100" placeholder="e.g. blue-ball"></label><label>State<input id="prop-state" maxlength="80" placeholder="e.g. scuffed"></label><label>State dimension<select id="prop-state-kind"><option value="">Unspecified</option><option value="angle">Angle</option><option value="fill">Fill level</option><option value="condition">Condition</option><option value="pose">Pose</option></select></label></details><button id="prop-done" class="primary">Done · add to catalogue</button><button id="prop-variant">Save as variant</button><button id="prop-hide">Hide / show placement</button><button id="prop-remove">Remove from canvas</button><button id="prop-export">Export selected prop JSON</button><button id="prop-png">Export selected prop PNG</button></div><hr><h3>Cat for scale</h3><label>Reference sequence<select id="prop-reference"></select></label><label><input id="prop-cat-visible" type="checkbox" checked>Show reference cat</label><label><input id="prop-cat-animate" type="checkbox" checked>Animate reference</label><label>Cat X<input id="prop-cat-x" type="number" min="0" max="72" value="32"></label><label>Cat Y<input id="prop-cat-y" type="number" min="0" max="40" value="32"></label><small>The cat is a separate 24×24 reference layer, excluded from captured props.</small></aside></div>`;
 dialog.querySelector('.props-layout').inert=true;
 const $=s=>dialog.querySelector(s),canvas=$('#prop-canvas'),ctx=canvas.getContext('2d');let cache;try{cache=JSON.parse(localStorage.getItem(PROP_CACHE)||'null');if(cache)validatePropWorkspace(cache.workspace);}catch{cache=null;}
 const themePanel=document.createElement('details');themePanel.className='prop-theme-proposals';$('#prop-edit-controls').after(themePanel);
 let workspace=cache?.workspace||newPropWorkspace(library.props||[],library.savedPropAssets||[]),etag=cache?.etag||null,dirty=!!cache?.dirty,ready=false,selectedId=null,box=null,tool='draw',zoom=4,gesture=null,undo=[],redo=[],referenceFrames=[],recoveryId=cache?.recoveryId||null,recoveryRetries=0;
 function local(){try{localStorage.setItem(PROP_CACHE,JSON.stringify({workspace,etag,dirty,recoveryId}));}catch{toast('Browser storage is full. Export the props workspace now.');}}
 const recovery=$('.props-recovery');
 function recoveryNotice(message,pending=false){recovery.hidden=false;recovery.open=pending;recovery.dataset.pending=String(pending);$('#props-recovery-message').textContent=message;$('#props-recover-merge').hidden=!pending;$('#props-reload').hidden=!pending;$('#props-recovery-download').hidden=!recoveryId;}
 const saver=createAutosaver({initial:dirty?[workspace]:[],write:async snapshot=>{if(!ready)throw Error('Loading shared workspace.');const response=await fetch('/api/props-workspace',{method:'PUT',headers:{'Content-Type':'application/json',...(etag?{'If-Match':etag}:{'If-None-Match':'*'})},body:JSON.stringify(snapshot)});if(!response.ok){const error=Error(response.status===409?'A newer workspace exists. Both copies are retained.':'Shared save unavailable. Browser draft retained.');error.status=response.status;throw error;}etag=response.headers.get('etag');},persist:pending=>{dirty=pending.length>0;local();},changed:(_,state,error)=>{if(state==='saved'){recoveryRetries=0;window.dispatchEvent(new CustomEvent('studio-asset-saved'));}$('#props-save-status').textContent=({pending:'Draft saved in browser',saving:'Saving workspace…',saved:'Workspace autosaved',offline:'Browser draft retained · offline',conflict:'Reconciling saved copies…'})[state]||error;$('#props-save-now').hidden=!['offline','conflict'].includes(state);if(state==='conflict'){recoveryNotice('Another saved copy exists. Your browser draft is retained. Reconcile to keep both sets of assets and canvas placements.',true);if(recoveryRetries++<2)queueMicrotask(()=>hydrate());}}});
 async function backup(saved){const response=await fetch('/api/props-recoveries',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({browser:workspace,saved})});if(!response.ok)throw Error('Could not back up both copies. Your draft is retained.');recoveryId=(await response.json()).id;local();}
 async function hydrate(force=false,manual=false){
  if(!manual&&(gesture||selectedId||box)){refreshPropCatalogue(workspace,library.props||[],library.savedPropAssets||[]);renderCatalogue();recoveryNotice('A newer copy exists. Finish the current prop with Done, then reconcile. Your canvas draft is retained.',true);return;}
  $('.props-layout').inert=true;
  try{const response=await fetch('/api/props-workspace');
   if(response.ok){const record=await response.json(),remoteEtag=response.headers.get('etag');validatePropWorkspace(record.workspace);
    if((force||dirty&&etag!==remoteEtag)&&JSON.stringify(workspace)!==JSON.stringify(record.workspace)){
     await backup(record.workspace);const merged=force?{workspace:record.workspace,recoveredAssets:0,recoveredPlacements:0}:reconcilePropWorkspaces(workspace,record.workspace,library.props||[],library.savedPropAssets||[]);
     workspace=merged.workspace;etag=remoteEtag;saver.loaded(workspace);selectedId=null;box=null;undo=[];redo=[];
     recoveryNotice(force?'Saved workspace loaded. Both original copies are backed up.':`Copies reconciled. Both originals are backed up${merged.recoveredAssets?' · '+merged.recoveredAssets+' edited assets kept as recovery variants':''}${merged.recoveredPlacements?' · '+merged.recoveredPlacements+' canvas edits recovered':''}.`);
     if(!force)save();
    }else if(!dirty||JSON.stringify(workspace)===JSON.stringify(record.workspace)){workspace=record.workspace;etag=remoteEtag;saver.loaded(workspace);selectedId=null;box=null;undo=[];redo=[];}
   }else if(response.status!==404)throw Error('Shared storage unavailable');
   ready=true;if(refreshPropCatalogue(workspace,library.props||[],library.savedPropAssets||[]))save();renderCatalogue();renderReferenceOptions();render();if(dirty){saver.queue(workspace);saver.flush();}
  }catch(error){ready=true;refreshPropCatalogue(workspace,library.props||[],library.savedPropAssets||[]);local();renderCatalogue();renderReferenceOptions();render();$('#props-save-status').textContent='Browser draft retained · save unavailable';$('#props-save-now').hidden=false;recoveryNotice(error.message||'Both copies are retained. Retry when shared storage is available.',true);}
  finally{dialog.classList.remove('props-loading');$('.props-layout').inert=false;}
 }
 $('#props-save-now').onclick=()=>hydrate(false,true);$('#props-recover-merge').onclick=()=>hydrate(false,true);$('#props-reload').onclick=()=>hydrate(true,true);
 $('#props-recovery-download').onclick=async()=>{try{const response=await fetch('/api/props-recoveries/'+recoveryId);if(!response.ok)throw Error('Recovery unavailable.');download('cat-props-original-copies.json',JSON.stringify(await response.json(),null,2));}catch(e){toast(e.message);}};
 function save(){validatePropWorkspace(workspace);dirty=true;local();saver.queue(workspace);}
 function snapshot(){undo.push(clone(workspace));if(undo.length>30)undo.shift();redo=[];}
 function changed(){save();render();}
 function safe(fn){try{fn();}catch(e){toast(e.message);}}
 function placement(){return workspace.instances.find(i=>i.id===selectedId);}
 function asset(){const i=placement();return i&&workspace.assets.find(a=>a.id===i.assetId);}
 function metadata(){return {mouthCarryable:$('#prop-mouth-carryable').checked,name:$('#prop-name').value,description:$('#prop-description').value,behaviourNotes:$('#prop-behaviour').value,familyId:$('#prop-family').value.trim(),stateKey:$('#prop-state').value.trim(),stateKind:$('#prop-state-kind').value,tags:$('#prop-tags').value.split(',').map(s=>s.trim()).filter(Boolean).slice(0,20).map(s=>s.slice(0,40))};}
 const artist=()=>$('#prop-artist').value;
 function select(i){selectedId=i?.id||null;box=null;const a=asset();$('#prop-name').value=a?.name||'';$('#prop-description').value=a?.description||'';$('#prop-behaviour').value=a?.behaviourNotes||'';$('#prop-tags').value=a?.tags.join(', ')||'';$('#prop-family').value=a?.familyId||'';$('#prop-state').value=a?.stateKey||'';$('#prop-state-kind').value=a?.stateKind||'';$('#prop-mouth-carryable').checked=!!propMouthCarryable(a);render();}
 function setTool(value){tool=value;for(const b of dialog.querySelectorAll('[data-prop-tool]'))b.setAttribute('aria-pressed',String(b.dataset.propTool===tool));$('#prop-canvas-hint').textContent=tool==='box'?'Drag a tight box around loose artwork. Give it a label and click Done.':tool==='move'?'Drag a prop by its bounding box. Arrow keys nudge the selected prop; Shift moves 8 pixels.':selectedId?'Painting the selected placement only. Click New drawing for loose artwork.':'Left-click draws; right-click erases. Box loose artwork when ready.';}
 for(const b of dialog.querySelectorAll('[data-prop-tool]'))b.onclick=()=>setTool(b.dataset.propTool);
 $('#prop-new').onclick=()=>{select(null);setTool('draw');};
 $('#prop-undo').onclick=()=>{if(!undo.length)return;redo.push(clone(workspace));workspace=undo.pop();selectedId=null;box=null;changed();renderCatalogue();renderReferenceOptions();};
 $('#prop-redo').onclick=()=>{if(!redo.length)return;undo.push(clone(workspace));workspace=redo.pop();selectedId=null;box=null;changed();renderCatalogue();renderReferenceOptions();};
 $('#prop-set-box').onclick=()=>safe(()=>{const values=['x','y','width','height'].map(k=>Number($('#prop-box-'+k).value));const [x,y,width,height]=values;if(!values.every(Number.isInteger)||x<0||y<0||width<1||height<1||x+width>96||y+height>64)throw Error('Capture box must fit within the canvas.');select(null);box={x,y,width,height};render();});
 $('#prop-done').onclick=()=>safe(()=>{snapshot();if(box){const i=captureProp(workspace,box,metadata(),artist());select(i);}else confirmProp(workspace,selectedId,metadata(),artist());box=null;changed();renderCatalogue();select(placement());saver.flush();toast('Prop saved in the catalogue.');});
 $('#prop-variant').onclick=()=>safe(()=>{snapshot();confirmProp(workspace,selectedId,metadata(),artist(),true);changed();renderCatalogue();select(placement());});
 $('#prop-hide').onclick=()=>{const i=placement();if(!i)return;snapshot();i.visible=!i.visible;changed();};
 $('#prop-remove').onclick=()=>{if(!placement())return;snapshot();workspace.instances=workspace.instances.filter(i=>i.id!==selectedId);select(null);changed();};
 $('#props-export').onclick=()=>download('cat-props-workspace.json',JSON.stringify(workspace,null,2));
 $('#prop-export').onclick=()=>{const a=asset();if(a)download(a.id+'.json',JSON.stringify(a,null,2));};
 $('#prop-png').onclick=()=>{const a=asset();if(!a)return;const c=document.createElement('canvas');c.width=a.width;c.height=a.height;paintMatrix(c.getContext('2d'),a.pixels,0,0,1);c.toBlob(blob=>download(a.id+'.png',blob,'image/png'));};
 $('#prop-search').oninput=renderCatalogue;$('#prop-catalogue-filter').onchange=renderCatalogue;
 $('#prop-zoom').onchange=()=>{zoom=Number($('#prop-zoom').value);draw();};$('#prop-grid').onchange=draw;
 for(const colour of ['#19222b','#ffffff','#4da6ff','#3ca272','#f3a65e','#e86458','#964252','#aa6627']){const b=document.createElement('button');b.className='prop-swatch';b.style.background=colour;b.title=colour;b.setAttribute('aria-label','Paint '+colour);b.onclick=()=>$('#prop-colour').value=colour;$('#prop-swatches').append(b);}
 function renderCatalogue(){
  const list=$('#prop-catalogue'),query=$('#prop-search').value.toLowerCase(),families=new Map(),sections=new Map();list.replaceChildren();
  const filter=$('#prop-catalogue-filter').value,matches=workspace.assets.filter(a=>(filter==='all'||(filter==='ai'?a.origin==='ai':a.origin!=='ai'))&&(a.name+' '+propFamilyLabel(a.familyId||'')+' '+(a.stateKey||'')+' '+a.origin+' '+a.tags.join(' ')).toLowerCase().includes(query));
  const drafts=workspace.assets.filter(a=>a.origin==='ai');$('#prop-catalogue-count').textContent=`${workspace.assets.length} assets · ${new Set(workspace.assets.map(a=>a.familyId||a.id)).size} families / individual props · ${drafts.length} AI drafts for review`;
  for(const a of matches){
   const sectionKey=a.origin==='ai'?'AI drafts · review candidates':'Originals & your saved props';
   if(!sections.has(sectionKey)){const section=document.createElement('section'),heading=document.createElement('h4');heading.textContent=sectionKey;section.append(heading);sections.set(sectionKey,section);list.append(section);}
   let parent=sections.get(sectionKey);if(a.familyId){const key=sectionKey+'/'+a.familyId;if(!families.has(key)){const group=document.createElement('details'),title=document.createElement('summary'),count=matches.filter(p=>p.familyId===a.familyId&&(p.origin==='ai')===(a.origin==='ai')).length;const icon=document.createElement('canvas');icon.width=a.width;icon.height=a.height;paintMatrix(icon.getContext('2d'),a.pixels,0,0,1);title.append(icon,document.createTextNode(propFamilyLabel(a.familyId)+` · ${count} states`));group.open=!!query;group.append(title);families.set(key,group);parent.append(group);}parent=families.get(key);}
   const b=document.createElement('button'),c=document.createElement('canvas'),label=document.createElement('span');b.className='prop-catalogue-item';c.width=a.width;c.height=a.height;paintMatrix(c.getContext('2d'),a.pixels,0,0,1);label.textContent=`${a.name} · ${a.width}×${a.height} · ${a.origin}`+(a.stateKey?` · ${a.stateKind||'state'}: ${a.stateKey}`:'');b.append(c,label);b.setAttribute('aria-label','Add prop '+a.name);b.onclick=()=>safe(()=>{snapshot();const i=addPropPlacement(workspace,a.id);select(i);setTool('move');changed();});parent.append(b);
  }
 }

 function renderReferenceOptions(){const select=$('#prop-reference');select.replaceChildren(new Option('No reference',''));for(const p of getSequences().filter(p=>!p.archived&&!p.deletedAt))select.add(new Option(p.name,p.projectId));select.value=workspace.reference.projectId;referenceFrames=getSequences().find(p=>p.projectId===select.value)?.frames||[];$('#prop-cat-visible').checked=workspace.reference.visible;$('#prop-cat-animate').checked=workspace.reference.animate;$('#prop-cat-x').value=workspace.reference.x;$('#prop-cat-y').value=workspace.reference.y;}
 for(const key of ['reference','cat-visible','cat-animate','cat-x','cat-y'])$('#prop-'+key).onchange=()=>{snapshot();workspace.reference={projectId:$('#prop-reference').value,x:Math.max(0,Math.min(72,Math.round(Number($('#prop-cat-x').value)||0))),y:Math.max(0,Math.min(40,Math.round(Number($('#prop-cat-y').value)||0))),visible:$('#prop-cat-visible').checked,animate:$('#prop-cat-animate').checked};renderReferenceOptions();changed();};
 function paintMatrix(c,pixels,x,y,scale){pixels.forEach((r,dy)=>r.forEach((colour,dx)=>{if(colour){c.fillStyle=colour;c.fillRect((x+dx)*scale,(y+dy)*scale,scale,scale);}}));}
 function draw(t=0){canvas.width=PROP_WIDTH*zoom;canvas.height=PROP_HEIGHT*zoom;for(let y=0;y<PROP_HEIGHT;y++)for(let x=0;x<PROP_WIDTH;x++){ctx.fillStyle=(x+y)%2?'#28313c':'#323e4b';ctx.fillRect(x*zoom,y*zoom,zoom,zoom);}paintMatrix(ctx,workspace.scratch,0,0,zoom);for(const i of workspace.instances)if(i.visible)paintMatrix(ctx,i.pixels,i.x,i.y,zoom);
 const ref=workspace.reference;if(ref.visible&&referenceFrames.length){const frame=referenceFrames[ref.animate?frameAt(referenceFrames,t):0];ctx.globalAlpha=.7;paintMatrix(ctx,frame.rows.map(r=>[...r].map(p=>p==='.'?null:'#ccd7e0')),ref.x,ref.y,zoom);ctx.globalAlpha=1;ctx.strokeStyle='#8ba6bb';ctx.setLineDash([3,4]);ctx.strokeRect(ref.x*zoom,ref.y*zoom,24*zoom,24*zoom);ctx.setLineDash([]);ctx.fillStyle='#ccd7e0';ctx.font='11px sans-serif';ctx.fillText('Cat · reference',ref.x*zoom,ref.y*zoom-3);}
 if($('#prop-grid').checked){ctx.strokeStyle='#8895a322';ctx.lineWidth=1;ctx.beginPath();for(let x=0;x<=PROP_WIDTH;x++){ctx.moveTo(x*zoom+.5,0);ctx.lineTo(x*zoom+.5,canvas.height);}for(let y=0;y<=PROP_HEIGHT;y++){ctx.moveTo(0,y*zoom+.5);ctx.lineTo(canvas.width,y*zoom+.5);}ctx.stroke();}
 for(const i of workspace.instances)if(i.visible){ctx.strokeStyle=i.id===selectedId?'#c2ed79':'#7b96aa';ctx.lineWidth=i.id===selectedId?2:1;ctx.setLineDash(i.id===selectedId?[]:[3,4]);ctx.strokeRect(i.x*zoom+.5,i.y*zoom+.5,i.width*zoom,i.height*zoom);}ctx.setLineDash([]);if(box){ctx.strokeStyle='#ffcd78';ctx.lineWidth=2;ctx.strokeRect(box.x*zoom,box.y*zoom,box.width*zoom,box.height*zoom);}}
 function render(){renderColourProposals(themePanel,asset());if(box)for(const key of ['x','y','width','height'])$('#prop-box-'+key).value=box[key];const i=placement(),a=asset();$('#prop-edit-controls').hidden=!box&&!i;$('#prop-selection-info').textContent=box?`New prop box · ${box.width}×${box.height}`:i?`${a.name} · ${i.width}×${i.height} · ${i.origin} · at (${i.x}, ${i.y})${i.dirty?' · unsaved catalogue edits':''}`:'Draw freely, then box a new prop; or select a catalogue prop to edit.';$('#prop-done').disabled=!box&&!i;$('#prop-done').textContent=box?'Done · add to catalogue':a?.source?.symbol?'Done · save edited variant':'Done · save prop';for(const key of ['variant','hide','remove','export','png'])$('#prop-'+key).disabled=!i;$('#prop-undo').disabled=!undo.length;$('#prop-redo').disabled=!redo.length;const list=$('#prop-placements');list.replaceChildren();for(const p of workspace.instances){const b=document.createElement('button'),a=workspace.assets.find(a=>a.id===p.assetId);b.textContent=`${p.visible?'◉':'○'} ${a.name}${p.dirty?' · edited':''}`;b.setAttribute('aria-pressed',String(p.id===selectedId));b.onclick=()=>{select(p);setTool('move');};list.append(b);}setTool(tool);draw();}
 function point(e){const r=canvas.getBoundingClientRect();return {x:Math.max(0,Math.min(PROP_WIDTH-1,Math.floor((e.clientX-r.left)/r.width*PROP_WIDTH))),y:Math.max(0,Math.min(PROP_HEIGHT-1,Math.floor((e.clientY-r.top)/r.height*PROP_HEIGHT)))};}
 function hit(p){return [...workspace.instances].reverse().find(i=>i.visible&&p.x>=i.x&&p.y>=i.y&&p.x<i.x+i.width&&p.y<i.y+i.height);}
 function fill(p,colour){const i=placement(),rows=i?.pixels||workspace.scratch,x=p.x-(i?.x||0),y=p.y-(i?.y||0);if(!rows[y]||x<0||x>=rows[0].length)return;const old=rows[y][x];if(old===colour)return;const stack=[{x,y}],seen=new Set(),points=[];while(stack.length){const q=stack.pop(),k=q.x+','+q.y;if(seen.has(k)||q.x<0||q.y<0||q.y>=rows.length||q.x>=rows[0].length||rows[q.y][q.x]!==old)continue;seen.add(k);points.push({x:q.x+(i?.x||0),y:q.y+(i?.y||0)});stack.push({x:q.x+1,y:q.y},{x:q.x-1,y:q.y},{x:q.x,y:q.y+1},{x:q.x,y:q.y-1});}paintProp(workspace,selectedId,points,colour,artist());}
 canvas.oncontextmenu=e=>e.preventDefault();canvas.onpointerdown=e=>safe(()=>{if(!ready||![0,2].includes(e.button))return;e.preventDefault();canvas.setPointerCapture(e.pointerId);const p=point(e);if(tool==='pick'&&e.button===0){const i=hit(p),c=i?i.pixels[p.y-i.y][p.x-i.x]:workspace.scratch[p.y][p.x];if(c)$('#prop-colour').value=c;return;}snapshot();gesture={start:p,last:p,button:e.button};if(tool==='move'&&e.button===0){const i=hit(p);select(i);if(i)gesture.offset={x:p.x-i.x,y:p.y-i.y};}else if(tool==='box'&&e.button===0){select(null);box=propBounds(p,p);}else{box=null;const colour=e.button===2||tool==='erase'?null:$('#prop-colour').value;if(tool==='fill'&&e.button===0)fill(p,colour);else paintProp(workspace,selectedId,[p],colour,artist());}render();});
 canvas.onpointermove=e=>{if(!gesture)return;safe(()=>{const p=point(e);if(tool==='move'&&gesture.button===0){const i=placement();if(i&&gesture.offset){i.x=Math.max(0,Math.min(PROP_WIDTH-i.width,p.x-gesture.offset.x));i.y=Math.max(0,Math.min(PROP_HEIGHT-i.height,p.y-gesture.offset.y));}}else if(tool==='box'&&gesture.button===0)box=propBounds(gesture.start,p);else if(tool!=='fill'&&tool!=='pick')paintProp(workspace,selectedId,lineCells(gesture.last,p),gesture.button===2||tool==='erase'?null:$('#prop-colour').value,artist());gesture.last=p;draw();});};
 canvas.onkeydown=e=>{const delta={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[e.key],i=placement();if(!delta||!i)return;e.preventDefault();snapshot();const step=e.shiftKey?8:1;i.x=Math.max(0,Math.min(PROP_WIDTH-i.width,i.x+delta[0]*step));i.y=Math.max(0,Math.min(PROP_HEIGHT-i.height,i.y+delta[1]*step));changed();};
 function end(){if(!gesture)return;gesture=null;safe(changed);}canvas.onpointerup=end;canvas.onpointercancel=end;
 let lastDraw=0;function animate(t){if(!dialog.hidden&&workspace.reference.animate&&t-lastDraw>100){lastDraw=t;draw(t);}requestAnimationFrame(animate);}requestAnimationFrame(animate);
 window.addEventListener('online',()=>saver.flush());window.addEventListener('pagehide',()=>saver.flush());document.addEventListener('visibilitychange',()=>{if(document.hidden)saver.flush();});
 setTool('draw');renderCatalogue();renderReferenceOptions();render();if(recoveryId)recoveryNotice('Exact originals from the last recovery remain available to download.');hydrate();return {open(){dialog.hidden=false;$('#prop-artist').value=actor();renderReferenceOptions();render();},close(){saver.flush();dialog.hidden=true;},find(name){$('#prop-search').value=name;renderCatalogue();}};
}
